  console.log('User not found by email maya.chen@email.com');
  // Try partial match
  const users = db.prepare(\"SELECT user_id, name, email FROM users WHERE email LIKE '%maya%' OR name LIKE '%maya%' OR name LIKE '%Maya%'\").all();
  console.log('Partial matches:', JSON.stringify(users, null, 2));
}
"

