node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Get user details
const user = db.prepare(\"SELECT * FROM users WHERE email = ?\").get('maya.chen@example.com');
console.log('=== USER DETAILS ===');
console.log('user_id:', user.user_id);
console.log('name:', user.name);
console.log('email:', user.email);
console.log('address:', user.address_json);
console.log('payment_methods:', user.payment_methods_json);

// Get orders for this user
const orders = db.prepare(\"SELECT * FROM orders WHERE customer_id = ?\").all(user.user_id);
console.log('\n=== ORDERS ===');
for (const o of orders) {
  console.log('order_id:', o.order_id, '| status:', o.status, '| date:', o.order_date, '| total_paid:', o.total_paid);
}
"

